diff --git a/crates/zero3-providers/src/weixin_clawbot.rs b/crates/zero3-providers/src/weixin_clawbot.rs
--- a/crates/zero3-providers/src/weixin_clawbot.rs
+++ b/crates/zero3-providers/src/weixin_clawbot.rs
@@ -486,1 +486,11 @@
-    std::fs::rename(&temp, path).context("atomically replace Weixin state")?;
+    match std::fs::rename(&temp, path) {
+        Ok(()) => {}
+        Err(error) if cfg!(windows) => {
+            if path.exists() {
+                std::fs::remove_file(path).context("replace existing Weixin state on Windows")?;
+            }
+            std::fs::rename(&temp, path)
+                .context("finish replacing Weixin state on Windows")?;
+        }
+        Err(error) => return Err(error).context("atomically replace Weixin state"),
+    }
